import { useEffect, useRef, useState } from 'react'
import { BrowserRouter, Link, NavLink, Navigate, Route, Routes, useNavigate, useParams } from 'react-router-dom'
import axios from 'axios'
import { AreaChart, Area, BarChart, Bar, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity, ArrowRight, Bell, BriefcaseBusiness, Building2, Check, ChevronRight, CircleHelp, ClipboardCheck, Download, FileText, Gauge, GraduationCap, LayoutDashboard, LogOut, Menu, Moon, Search, ShieldCheck, Sparkles, Sun, Target, Users, X, Zap } from 'lucide-react'

const api = axios.create({ baseURL: '/api/v1' })
api.interceptors.request.use((config) => { const token = localStorage.getItem('skilltrack_token'); if (token) config.headers.Authorization = `Bearer ${token}`; return config })
let refreshing = null
api.interceptors.response.use((response) => response, async (error) => { const original = error.config; if (error.response?.status === 401 && !original?._retry && localStorage.getItem('skilltrack_refresh')) { original._retry = true; refreshing ||= api.post('/auth/refresh', { refresh_token: localStorage.getItem('skilltrack_refresh') }); try { const { data } = await refreshing; refreshing = null; localStorage.setItem('skilltrack_token', data.access_token); if (data.refresh_token) localStorage.setItem('skilltrack_refresh', data.refresh_token); original.headers.Authorization = `Bearer ${data.access_token}`; return api(original) } catch { refreshing = null; localStorage.removeItem('skilltrack_token'); localStorage.removeItem('skilltrack_refresh'); localStorage.removeItem('skilltrack_user'); window.location.href = '/login' } } return Promise.reject(error) })
const demoAccounts = [
  { label: 'Login as Student', person: 'Aarav Sharma', email: 'aarav.sharma@skilltrack.demo', password: 'Demo@123', role: 'student', color: '#4F46E5' },
  { label: 'Login as Recruiter', person: 'Priya · TechNova', email: 'priya@technova.demo', password: 'Demo@123', role: 'recruiter', color: '#0F766E' },
  { label: 'Login as Admin', person: 'Placement office', email: 'admin@skilltrack.demo', password: 'Admin@123', role: 'admin', color: '#B45309' },
]
const roleHome = { student: '/student', recruiter: '/recruiter', admin: '/admin' }
const navByRole = {
  student: [{ to: '/student', label: 'Overview', icon: LayoutDashboard }, { to: '/student/jobs', label: 'Find jobs', icon: BriefcaseBusiness }, { to: '/student/applications', label: 'My applications', icon: ClipboardCheck }, { to: '/student/profile', label: 'Profile', icon: Users }, { to: '/student/resume', label: 'Resume intelligence', icon: FileText }, { to: '/notifications', label: 'Notifications', icon: Bell }],
  recruiter: [{ to: '/recruiter', label: 'Recruiter dashboard', icon: LayoutDashboard }, { to: '/recruiter/applicants', label: 'Applicants', icon: Users }, { to: '/notifications', label: 'Notifications', icon: Bell }],
  admin: [{ to: '/admin', label: 'Control center', icon: LayoutDashboard }, { to: '/notifications', label: 'Notifications', icon: Bell }],
}

function App() {
  const [user, setUser] = useState(() => JSON.parse(localStorage.getItem('skilltrack_user') || 'null'))
  const [dark, setDark] = useState(() => localStorage.getItem('skilltrack_theme') === 'dark')
  const [toast, setToast] = useState(null)
  useEffect(() => { document.documentElement.dataset.theme = dark ? 'dark' : 'light'; localStorage.setItem('skilltrack_theme', dark ? 'dark' : 'light') }, [dark])
  const login = async (email, password) => { try { const { data } = await api.post('/auth/login', { email, password }); localStorage.setItem('skilltrack_token', data.access_token); localStorage.setItem('skilltrack_refresh', data.refresh_token); localStorage.setItem('skilltrack_user', JSON.stringify(data.user)); setUser(data.user); return data.user } catch (e) { setToast(e.response?.data?.error?.message || e.response?.data?.detail || 'Unable to sign in'); throw e } }
  const logout = () => { localStorage.removeItem('skilltrack_token'); localStorage.removeItem('skilltrack_refresh'); localStorage.removeItem('skilltrack_user'); setUser(null) }
  return <BrowserRouter><AppRoutes user={user} setUser={setUser} login={login} logout={logout} dark={dark} setDark={setDark} toast={toast} setToast={setToast} /></BrowserRouter>
}

function AppRoutes({ user, setUser, login, logout, dark, setDark, toast, setToast }) {
  return <>
    {user ? <Shell user={user} logout={logout} dark={dark} setDark={setDark} /> : null}
    <Routes>
      <Route path="/" element={<Home />} />
      <Route path="/login" element={user ? <Navigate to={roleHome[user.role]} replace /> : <Login onLogin={login} />} /><Route path="/register" element={user ? <Navigate to={roleHome[user.role]} replace /> : <Register />} />
      <Route path="/student" element={<Protected user={user} role="student"><StudentDashboard user={user} setToast={setToast} /></Protected>} /><Route path="/student/profile" element={<Protected user={user} role="student"><ProfilePage setToast={setToast} /></Protected>} />
      <Route path="/student/jobs" element={<Protected user={user} role="student"><JobsPage /></Protected>} />
      <Route path="/student/jobs/:id" element={<Protected user={user} role="student"><JobDetail setToast={setToast} /></Protected>} />
      <Route path="/student/applications" element={<Protected user={user} role="student"><ApplicationsPage /></Protected>} />
      <Route path="/student/resume" element={<Protected user={user} role="student"><ResumePage setToast={setToast} /></Protected>} />
      <Route path="/recruiter" element={<Protected user={user} role="recruiter"><RecruiterDashboard /></Protected>} />
      <Route path="/recruiter/applicants" element={<Protected user={user} role="recruiter"><ApplicantsPage setToast={setToast} /></Protected>} />
      <Route path="/admin" element={<Protected user={user} role="admin"><AdminDashboard setToast={setToast} /></Protected>} />
      <Route path="/notifications" element={<Protected user={user}><NotificationsPage /></Protected>} />
      <Route path="*" element={<Navigate to={user ? roleHome[user.role] : '/'} replace />} />
    </Routes>
    {toast && <div className="toast"><Check size={16} />{toast}<button onClick={() => setToast(null)}><X size={14} /></button></div>}
  </>
}

function Protected({ user, role, children }) { if (!user) return <Navigate to="/login" replace />; if (role && user.role !== role) return <Navigate to={roleHome[user.role]} replace />; return children }

function Shell({ user, logout, dark, setDark }) {
  const [mobile, setMobile] = useState(false)
  const [notifications, setNotifications] = useState(0)
  useEffect(() => { if (user) api.get('/notifications').then(r => setNotifications(r.data.unread)).catch(() => {}) }, [user])
  const initials = user.name?.split(' ').map((x) => x[0]).join('').slice(0, 2) || 'ST'
  return <div className="app-shell"><aside className={`sidebar ${mobile ? 'open' : ''}`}><div className="brand"><div className="brand-mark"><Activity size={19} /></div><span>SkillTrack</span><button className="icon-btn mobile-close" onClick={() => setMobile(false)}><X size={18} /></button></div><div className="workspace-label">{user.role === 'student' ? 'Student workspace' : user.role === 'recruiter' ? 'Recruiter workspace' : 'Placement office'}</div><nav>{navByRole[user.role].map(({ to, label, icon: Icon }) => <NavLink key={to} to={to} end={to === roleHome[user.role]} className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`} onClick={() => setMobile(false)}><Icon size={18} /><span>{label}</span>{label === 'Notifications' && notifications > 0 ? <span className="nav-count">{notifications}</span> : null}</NavLink>)}</nav><div className="sidebar-bottom"><div className="ai-card"><div className="eyebrow"><Sparkles size={13} /> AI mode</div><strong>Offline demo</strong><span>Explainable fallback is active</span></div><button className="nav-item" onClick={logout}><LogOut size={18} /><span>Sign out</span></button></div></aside><header className="topbar"><button className="icon-btn mobile-menu" onClick={() => setMobile(true)}><Menu size={20} /></button><div className="crumb">Workspace <ChevronRight size={13} /> <strong>{user.role === 'student' ? 'Student' : user.role === 'recruiter' ? 'Recruiter' : 'Admin'}</strong></div><div className="top-actions"><span className="ai-badge"><span className="status-dot" /> AI · offline demo</span><button className="icon-btn" onClick={() => setDark(!dark)} title="Toggle theme">{dark ? <Sun size={18} /> : <Moon size={18} />}</button><Link className="notification-btn" to="/notifications"><Bell size={18} />{notifications > 0 && <span>{notifications}</span>}</Link><div className="avatar" style={{ background: user.role === 'student' ? '#4F46E5' : user.role === 'recruiter' ? '#0F766E' : '#B45309' }}>{initials}</div></div></header></div>
}

function Home() { const [stats, setStats] = useState({ students: 0, jobs: 0, applications: 0, placements: 0, avg_match: 0 }); useEffect(() => { api.get('/stats/public').then(r => setStats(r.data)).catch(() => {}) }, []); return <div className="public-page"><header className="public-nav"><Link to="/" className="brand public-brand"><div className="brand-mark"><Activity size={19} /></div><span>SkillTrack</span></Link><div className="public-nav-actions"><span className="ai-badge"><span className="status-dot" /> AI · offline demo</span><Link className="btn btn-outline" to="/login">Sign in</Link></div></header><main><section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot" /> Placement intelligence, made explainable</div><h1>Turn campus talent into <em>career momentum.</em></h1><p>SkillTrack helps students find their edge, recruiters shortlist with confidence, and placement teams see the whole pipeline — in one calm workspace.</p><div className="hero-actions"><Link className="btn btn-primary btn-lg" to="/login">Explore the demo <ArrowRight size={17} /></Link><a className="text-link" href="#how">See how it works <ChevronRight size={15} /></a></div><div className="proof-row"><div className="proof-avatars"><span>AS</span><span>SG</span><span>NG</span><span>+7</span></div><span><strong>{stats.students}</strong> demo student profiles ready to explore</span></div></div><div className="hero-visual"><div className="orb orb-one" /><div className="orb orb-two" /><div className="hero-card main-score"><div className="hero-card-top"><span>Average match</span><span className="trend">Live data</span></div><div className="big-score">{stats.avg_match || 0}<span>/100</span></div><div className="score-track"><i style={{ width: `${stats.avg_match || 0}%` }} /></div><div className="hero-card-bottom"><span>Skill alignment</span><span>Strong</span></div></div><div className="hero-card mini-card"><div className="mini-icon teal"><Target size={16} /></div><div><strong>{stats.placements}</strong><span>placements</span></div></div><div className="hero-card insight-card"><div className="eyebrow"><Sparkles size={12} /> Skill gap insight</div><strong>Skill gaps become actionable</strong><span>{stats.jobs} approved roles are currently visible</span></div></div></section><section className="stat-strip">{[[stats.students, 'students ready'], [stats.jobs, 'approved roles'], [stats.applications, 'applications tracked'], [stats.placements, 'placements']].map(([value, label]) => <div key={label}><strong>{value}</strong><span>{label}</span></div>)}</section><section className="how-section" id="how"><div className="section-kicker">A better placement loop</div><h2>From potential to proof, in three steps.</h2><div className="steps"><Step number="01" title="See your signal" text="Parse a resume, map your skills, and get a fit score you can actually understand." icon={<Gauge />} /><Step number="02" title="Make the next move" text="Discover roles, surface skill gaps, and build a plan that is specific to the opportunity." icon={<Zap />} /><Step number="03" title="Shortlist with trust" text="Recruiters see ranked, explainable applicants — with blind screening built in from the start." icon={<ShieldCheck />} /></div></section><section className="feature-section"><div className="feature-card feature-indigo"><Sparkles size={22} /><h3>Explainable AI scoring</h3><p>Weighted skills, semantic fit, eligibility and experience — never a black-box rejection.</p><span>45% skill · 30% semantic · 15% eligibility · 10% experience</span></div><div className="feature-card feature-teal"><Users size={22} /><h3>Fairer shortlists</h3><p>Blind mode removes identity signals server-side, keeping the conversation on evidence.</p><span>Decision support, not automatic rejection</span></div><div className="feature-card feature-slate"><Building2 size={22} /><h3>One source of truth</h3><p>Dashboards, history, notifications and insights that let teams move together.</p><span>Student · recruiter · admin</span></div></section></main><footer className="public-footer"><div className="brand"><div className="brand-mark"><Activity size={18} /></div><span>SkillTrack</span></div><span>Built for the next placement season.</span><span>Demo environment · synthetic data</span></footer></div> }
function Step({ number, title, text, icon }) { return <div className="step"><div className="step-number">{number}</div><div className="step-icon">{icon}</div><h3>{title}</h3><p>{text}</p></div> }

function Login({ onLogin }) { const [loading, setLoading] = useState(false); const [error, setError] = useState(''); const navigate = useNavigate(); const submit = async (account) => { setLoading(true); setError(''); try { const u = await onLogin(account.email, account.password); navigate(roleHome[u.role]) } catch (e) { setError('Please check the demo credentials and try again.') } finally { setLoading(false) } }; return <div className="login-page"><Link to="/" className="brand login-brand"><div className="brand-mark"><Activity size={19} /></div><span>SkillTrack</span></Link><div className="login-wrap"><div className="login-intro"><div className="eyebrow"><span className="eyebrow-dot" /> Your placement workspace</div><h1>Progress should feel <em>visible.</em></h1><p>Use one of the demo personas to explore the complete SkillTrack experience. No setup, no typing, just a fully populated workspace.</p><div className="login-note"><ShieldCheck size={18} /><div><strong>Safe demo environment</strong><span>All data is synthetic and resettable from the admin console.</span></div></div></div><div className="login-card"><div className="card-head"><div><span className="section-kicker">Quick access</span><h2>Choose a workspace</h2></div><span className="ai-badge"><span className="status-dot" /> offline</span></div>{demoAccounts.map(account => <button key={account.email} className="demo-account" onClick={() => submit(account)} disabled={loading}><div className="demo-avatar" style={{ background: account.color }}>{account.person.split(' ').map(x => x[0]).join('').slice(0, 2)}</div><div className="demo-copy"><strong>{account.label}</strong><span>{account.person}</span></div><ArrowRight size={17} /></button>)}{error && <div className="inline-error">{error}</div>}<div className="login-divider"><span>or continue with credentials</span></div><p className="muted small">Demo passwords are pre-configured. Student and recruiter: <strong>Demo@123</strong> · Admin: <strong>Admin@123</strong></p></div></div></div> }

function Page({ title, eyebrow, subtitle, actions, children }) { return <main className="page"><div className="page-header"><div><div className="section-kicker">{eyebrow}</div><h1>{title}</h1>{subtitle && <p>{subtitle}</p>}</div>{actions && <div className="page-actions">{actions}</div>}</div>{children}</main> }
function StatCard({ label, value, meta, icon: Icon, tone = 'indigo' }) { return <div className={`stat-card tone-${tone}`}><div className="stat-top"><span>{label}</span><div className="stat-icon"><Icon size={17} /></div></div><strong>{value}</strong><span className="stat-meta">{meta}</span></div> }
function ScoreRing({ score, size = 'md' }) { const value = Math.round(score || 0); return <div className={`score-ring ${size} ${value >= 80 ? 'high' : value >= 60 ? 'mid' : 'low'}`} style={{ '--score': `${value * 3.6}deg` }}><div><strong>{value}</strong><span>/100</span></div></div> }
function SkillChip({ children, type = 'neutral' }) { return <span className={`skill-chip ${type}`}>{type === 'matched' && <Check size={12} />}{children}</span> }
function StatusBadge({ status }) { return <span className={`status-badge ${status?.toLowerCase().replace(' ', '-')}`}>{status || 'Scoring...'}</span> }
function Empty({ icon: Icon = CircleHelp, title, text }) { return <div className="empty"><Icon size={28} /><strong>{title}</strong><span>{text}</span></div> }

function StudentDashboard({ user, setToast }) { const [data, setData] = useState(null); useEffect(() => { api.get('/students/me/dashboard').then(r => setData(r.data)).catch(() => {}) }, []); if (!data) return <Loading />; const profile = data.profile || {}; return <Page eyebrow="Student workspace" title={`Good morning, ${profile.full_name?.split(' ')[0] || user.name.split(' ')[0]}.`} subtitle="Your next opportunity is closer than the last one." actions={<Link className="btn btn-primary" to="/student/jobs"><Search size={16} /> Find a role</Link>}><div className="banner"><div className="banner-icon"><Sparkles size={19} /></div><div><strong>Your profile is telling a clear story.</strong><span>Complete your resume to unlock more relevant matches and stronger recruiter signals.</span></div><Link to="/student/resume" className="btn btn-light">Improve profile <ArrowRight size={15} /></Link></div><div className="stats-grid"> <StatCard label="Applications" value={data.stats.applications} meta="Submitted applications" icon={ClipboardCheck} /><StatCard label="Shortlisted" value={data.stats.shortlisted} meta="Shortlisted + interview" icon={Target} tone="teal" /><StatCard label="Interviews" value={data.stats.interviews} meta="Current pipeline" icon={Users} tone="amber" /><StatCard label="Average match" value={`${data.stats.avg_match}%`} meta={`${data.stats.profile_completion}% profile complete`} icon={Gauge} tone="green" /></div><div className="dashboard-grid"><section className="panel recommendations"><div className="panel-head"><div><span className="section-kicker">Curated for you</span><h2>Recommended roles</h2></div><Link className="text-link" to="/student/jobs">View all <ArrowRight size={14} /></Link></div><div className="recommend-list">{data.recommendations.map(job => <Link className="recommend-row" to={`/student/jobs/${job.id}`} key={job.id}><div className="company-logo">{job.company.slice(0, 2).toUpperCase()}</div><div className="recommend-main"><strong>{job.title}</strong><span>{job.company} · {job.location}</span><div className="chip-row">{job.mandatory_skills.slice(0, 3).map(s => <SkillChip key={s}>{s}</SkillChip>)}</div></div><ScoreRing score={job.fit?.score || 0} size="sm" /></Link>)}</div></section><section className="panel skill-gap-panel"><div className="panel-head"><div><span className="section-kicker">Your next unlock</span><h2>Skill gap radar</h2></div><span className="ai-badge"><Sparkles size={12} /> AI insight</span></div><p className="panel-copy">Build these skills to unlock more high-fit roles in your target market.</p><div className="gap-list">{data.skill_gaps.map((skill) => <div className="gap-row" key={skill}><span>{skill}</span><div className="gap-track"><i style={{ width: '100%' }} /></div><span className="gap-label">Missing</span></div>)}</div><Link className="btn btn-secondary full" to="/student/resume">See my resume feedback <ArrowRight size={15} /></Link></section></div><section className="panel"><div className="panel-head"><div><span className="section-kicker">Live pipeline</span><h2>Recent applications</h2></div><Link className="text-link" to="/student/applications">Open tracker <ArrowRight size={14} /></Link></div><ApplicationTable items={data.applications} /></section></Page> }
function ApplicationTable({ items }) { if (!items?.length) return <Empty title="No applications yet" text="Explore a role to start your placement journey." />; return <div className="table-wrap"><table><thead><tr><th>Role</th><th>Company</th><th>Match</th><th>Status</th><th>Applied</th></tr></thead><tbody>{items.map(item => <tr key={item.id}><td><strong>{item.title}</strong><span className="cell-sub">{item.location}</span></td><td>{item.company}</td><td><span className="table-score">{item.ats_score ? `${Math.round(item.ats_score)}%` : 'Scoring...'}</span></td><td><StatusBadge status={item.status} /></td><td className="muted">Recently</td></tr>)}</tbody></table></div> }

function JobsPage() { const [jobs, setJobs] = useState([]); const [q, setQ] = useState(''); const [sort, setSort] = useState('latest'); const load = () => api.get('/jobs', { params: { q, sort } }).then(r => setJobs(r.data.items)).catch(() => setJobs([])); useEffect(load, [sort]); return <Page eyebrow="Opportunity board" title="Find your next role" subtitle="Search approved openings ranked by fit, not just keywords." actions={<div className="search-field"><Search size={16} /><input placeholder="Search title, skill or company" value={q} onChange={e => setQ(e.target.value)} onKeyDown={e => e.key === 'Enter' && load()} /></div>}><div className="filter-row"><span className="muted">{jobs.length} roles in your market</span><div className="select-wrap"><span>Sort by</span><select value={sort} onChange={e => setSort(e.target.value)}><option value="latest">Newest</option><option value="salary">Salary</option><option value="match">Best match</option></select></div></div><div className="jobs-grid">{jobs.map(job => <Link to={`/student/jobs/${job.id}`} className="job-card" key={job.id}><div className="job-card-top"><div className="company-logo large">{job.company.slice(0, 2).toUpperCase()}</div><span className="job-type">{job.job_type}</span></div><h3>{job.title}</h3><p className="job-company">{job.company} <span>·</span> {job.location}</p><p className="job-desc">{job.description.slice(0, 130)}…</p><div className="chip-row">{job.mandatory_skills.slice(0, 4).map(s => <SkillChip key={s} type={job.fit?.matched?.includes(s) ? 'matched' : 'neutral'}>{s}</SkillChip>)}</div><div className="job-card-footer"><div><span className="salary">{job.salary_min < 100000 ? `₹${job.salary_min.toLocaleString()}/mo` : `₹${(job.salary_min / 100000).toFixed(1)}–${(job.salary_max / 100000).toFixed(1)} LPA`}</span><span className="deadline">Closes {new Date(job.deadline).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}</span></div><ScoreRing score={job.fit?.score || 72} size="sm" /></div></Link>)}</div></Page> }

function JobDetail({ setToast }) { const { id } = useParams(); const [job, setJob] = useState(null); const [questions, setQuestions] = useState(null); const navigate = useNavigate(); useEffect(() => { api.get(`/jobs/${id}`).then(r => setJob(r.data)).catch(() => {}) }, [id]); if (!job) return <Loading />; const apply = async () => { try { await api.post('/applications', { job_id: Number(id) }); setToast('Application submitted — scoring in progress'); setJob({ ...job, application: { status: 'Scoring...' } }) } catch (e) { setToast(e.response?.data?.detail || 'Could not apply') } }; const ask = async () => { const { data } = await api.post('/ai/interview-questions', null, { params: { job_id: id } }); setQuestions(data.questions) }; return <Page eyebrow="Role details" title={job.title} subtitle={`${job.company} · ${job.location} · ${job.job_type}`} actions={<button className="btn btn-outline" onClick={() => navigate('/student/jobs')}><ArrowRight size={15} style={{ transform: 'rotate(180deg)' }} /> Back to roles</button>}><div className="detail-layout"><article className="detail-main"><div className="company-banner"><div className="company-logo large">{job.company.slice(0, 2).toUpperCase()}</div><div><strong>{job.company}</strong><span>{job.industry} · {job.location}</span></div><span className="approval-badge"><ShieldCheck size={13} /> Approved</span></div><div className="panel prose"><div className="panel-head"><h2>About the role</h2><span className="muted">Closes {new Date(job.deadline).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}</span></div><p>{job.description}</p><h3>What you bring</h3><div className="chip-row">{job.mandatory_skills.map(s => <SkillChip key={s} type="matched">{s}</SkillChip>)}{job.optional_skills.map(s => <SkillChip key={s}>{s}</SkillChip>)}</div><div className="salary-callout"><span>Compensation</span><strong>{job.salary_min < 100000 ? `₹${job.salary_min.toLocaleString()}–₹${job.salary_max.toLocaleString()} / month` : `₹${(job.salary_min / 100000).toFixed(1)}–${(job.salary_max / 100000).toFixed(1)} LPA`}</strong></div></div></article><aside className="detail-side"><div className="panel fit-panel"><div className="panel-head"><div><span className="section-kicker">Your fit</span><h2>Explainable score</h2></div><span className="ai-badge"><Sparkles size={12} /> AI</span></div><div className="fit-score"><ScoreRing score={job.fit?.score || 0} size="lg" /><div><strong>{job.fit?.score >= 80 ? 'Strong alignment' : 'Promising foundation'}</strong><span>Compared to role requirements</span></div></div><div className="fit-section"><span className="fit-label">Matched skills</span><div className="chip-row">{(job.fit?.matched || []).map(s => <SkillChip key={s} type="matched">{s}</SkillChip>)}</div></div><div className="fit-section"><span className="fit-label">Missing skills</span><div className="chip-row">{(job.fit?.missing || []).map(s => <SkillChip key={s} type="missing">{s}</SkillChip>)}</div></div><div className={`eligibility ${job.fit?.eligibility?.passed ? 'passed' : 'flagged'}`}><span className="eligibility-icon">{job.fit?.eligibility?.passed ? <Check size={15} /> : <CircleHelp size={15} />}</span><div><strong>{job.fit?.eligibility?.passed ? 'Eligibility looks good' : 'Eligibility needs review'}</strong><span>{job.fit?.eligibility?.reasons?.[0]}</span></div></div><p className="disclaimer">Scores are decision support, never an automatic rejection.</p>{job.application ? <button className="btn btn-secondary full" disabled><Check size={15} /> {job.application.status === 'Scoring...' ? 'Scoring…' : `Applied · ${job.application.status}`}</button> : <button className="btn btn-primary full" onClick={apply}>Apply with my profile <ArrowRight size={15} /></button>}<button className="btn btn-ghost full" onClick={ask}><Sparkles size={15} /> Generate interview questions</button>{questions && <div className="question-list">{questions.slice(0, 4).map((q, i) => <div key={q}><span>0{i + 1}</span>{q}</div>)}</div>}</div></aside></div></Page> }

function ApplicationsPage() {
  const [data, setData] = useState(null); const [view, setView] = useState('list')
  const load = () => api.get('/applications/me').then(r => setData(r.data)).catch(() => {})
  useEffect(() => { load() }, [])
  useEffect(() => {
    if (!data?.items?.some(x => x.status === 'Scoring...')) return
    const timer = setInterval(load, 1200); return () => clearInterval(timer)
  }, [data])
  if (!data) return <Loading />
  const stages = ['Applied', 'Under Review', 'Shortlisted', 'Interview', 'Selected', 'Rejected']
  return <Page eyebrow="Application tracker" title="My applications" subtitle="A clear view of every conversation, from first click to final decision.">
    <div className="application-summary"><div><span className="section-kicker">Pipeline health</span><strong>{data.total} conversations</strong><span className="muted">Scores refresh automatically while processing</span></div><div className="role-toggle"><button className={view === 'list' ? 'active' : ''} onClick={() => setView('list')}>List</button><button className={view === 'kanban' ? 'active' : ''} onClick={() => setView('kanban')}>Kanban</button></div></div>
    {view === 'list' ? <div className="applications-list">{data.items.map(item => { const current = stages.indexOf(item.status); return <div className="application-card" key={item.id}><div className="application-main"><div className="company-logo">{item.company.slice(0, 2).toUpperCase()}</div><div><h3>{item.title}</h3><p>{item.company} · {item.location}</p><div className="timeline">{stages.slice(0, 5).map((step, i) => <div className={`timeline-step ${current >= i && item.status !== 'Rejected' ? 'done' : ''}`} key={step}><span>{current >= i && item.status !== 'Rejected' ? <Check size={11} /> : i + 1}</span><small>{step}</small></div>)}</div></div></div><div className="application-meta"><ScoreRing score={item.ats_score || 0} size="sm" /><StatusBadge status={item.status} /></div></div> })}</div> : <div className="kanban-grid">{['Applied','Under Review','Shortlisted','Interview','Selected'].map(stage => <section className="panel" key={stage}><div className="panel-head"><h2>{stage}</h2><span className="tag-open">{data.items.filter(x => x.status === stage).length}</span></div>{data.items.filter(x => x.status === stage).map(item => <div className="mini-job" key={item.id}><div><strong>{item.title}</strong><span>{item.company}</span></div><ScoreRing score={item.ats_score || 0} size="sm" /></div>)}</section>)}</div>}
  </Page>
}
function ResumePage({ setToast }) {
  const [feedback, setFeedback] = useState(null)
  const [parsed, setParsed] = useState(null)
  const [selectedSkills, setSelectedSkills] = useState([])
  const [uploading, setUploading] = useState(false)
  const fileRef = useRef(null)

  const upload = async (file) => {
    if (!file) return
    setUploading(true)
    try {
      const form = new FormData()
      form.append('file', file)
      const { data } = await api.post('/students/me/resume', form, { headers: { 'Content-Type': 'multipart/form-data' } })
      setParsed(data)
      setSelectedSkills(data.skills.map(x => x.name))
      setToast(`Parsed ${data.skills.length} canonical skills from your resume`)
    } catch (e) {
      setToast(e.response?.data?.detail || 'Resume parsing failed')
    } finally { setUploading(false) }
  }

  const confirm = async () => {
    try {
      await api.post('/students/me/resume/confirm-skills', selectedSkills)
      setToast('Resume skills confirmed and added to your profile')
    } catch (e) { setToast(e.response?.data?.detail || 'Could not confirm skills') }
  }

  const loadFeedback = async () => {
    try {
      const { data } = await api.post('/ai/resume-feedback')
      setFeedback(data)
      setToast('Resume feedback refreshed from your stored evidence')
    } catch (e) { setToast(e.response?.data?.detail || 'Could not generate feedback') }
  }

  return <Page eyebrow="Resume intelligence" title="Make your signal stronger" subtitle="Upload once, inspect the real parser evidence, then confirm what should shape your fit scores.">
    <div className="resume-grid">
      <div className="panel upload-panel">
        <div className="dropzone">
          <div className="upload-icon"><FileText size={24} /></div>
          <h2>{uploading ? 'Parsing your resume…' : 'Upload your resume'}</h2>
          <p>PDF only · max 5 MB · text extraction + taxonomy matching</p>
          <input ref={fileRef} type="file" accept="application/pdf,.pdf" hidden onChange={e => upload(e.target.files?.[0])} />
          <button className="btn btn-primary" onClick={() => fileRef.current?.click()} disabled={uploading}><Download size={15} /> {uploading ? 'Parsing…' : 'Choose a PDF'}</button>
        </div>
        <div className="sample-download"><div><span className="section-kicker">Presentation shortcut</span><strong>Download your generated sample resume</strong><span>Use it to demonstrate real PDF parsing and evidence extraction.</span></div><a className="btn btn-secondary" href="/api/v1/students/me/sample-resume" target="_blank" rel="noreferrer"><Download size={15} /> Download sample</a></div>
      </div>
      <div className="panel">
        <div className="panel-head"><div><span className="section-kicker">Parser preview</span><h2>We found these skills</h2></div>{parsed && <span className="ai-badge"><Check size={12} /> Parsed</span>}</div>
        {!parsed ? <Empty icon={FileText} title="No new resume parsed yet" text="Upload a PDF to see canonical skills, evidence snippets and source sections." /> : <>
          <p className="muted">{parsed.sections?.join(' · ')} · {parsed.word_count || 0} extracted words</p>
          <div className="evidence-list">{parsed.skills.map((skill) => <button className="evidence-row" key={skill.name} onClick={() => setSelectedSkills(selectedSkills.includes(skill.name) ? selectedSkills.filter(x => x !== skill.name) : [...selectedSkills, skill.name])}><div className="evidence-check">{selectedSkills.includes(skill.name) ? <Check size={13} /> : null}</div><div><strong>{skill.name}</strong><span>{skill.section} · “{skill.evidence}”</span></div><SkillChip type={selectedSkills.includes(skill.name) ? 'matched' : 'neutral'}>{selectedSkills.includes(skill.name) ? 'Selected' : 'Add'}</SkillChip></button>)}</div>
          <button className="btn btn-secondary full" onClick={confirm}>Confirm selected skills <Check size={15} /></button>
        </>}
      </div>
    </div>
    <div className="panel feedback-panel"><div className="panel-head"><div><span className="section-kicker">AI resume coach</span><h2>Feedback that moves the needle</h2></div><button className="btn btn-outline" onClick={loadFeedback}><Sparkles size={15} /> Generate feedback</button></div>{feedback ? <div className="feedback-grid"><div><h3>What is working</h3>{feedback.strengths.map(x => <p key={x}><Check size={14} /> {x}</p>)}</div><div><h3>Close the gaps</h3>{feedback.gaps.map(x => <p key={x}><CircleHelp size={14} /> {x}</p>)}</div><div className="rewrite"><span className="section-kicker">Rewritten bullet</span><p>“{feedback.rewrite}”</p></div></div> : <Empty icon={Sparkles} title="Your resume has untapped signal" text="Generate feedback from the resume, skills and projects stored in your profile." />}</div>
  </Page>
}
function RecruiterDashboard() {
  const [data, setData] = useState(null)
  const [showPost, setShowPost] = useState(false)
  const [form, setForm] = useState({ title: '', description: '', location: 'Remote', job_type: 'Full-time', salary_min: 0, salary_max: 0, min_cgpa: 0, deadline: new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10), mandatory_skills: [], optional_skills: [] })
  const [skillText, setSkillText] = useState('')
  const [suggesting, setSuggesting] = useState(false)
  const load = () => api.get('/recruiter/dashboard').then(r => setData(r.data)).catch(() => {})
  useEffect(load, [])
  const chart = data ? Object.entries(data.status_funnel).map(([name, value]) => ({ name: name.replace('Under Review', 'Review'), value })) : []
  const post = async () => {
    try { await api.post('/jobs', form); setShowPost(false); setForm({ ...form, title: '', description: '', mandatory_skills: [], optional_skills: [] }); await load() } catch (e) { alert(e.response?.data?.detail || 'Could not create job') }
  }
  const suggest = async () => {
    if (!form.description.trim()) return
    setSuggesting(true)
    try { const { data: result } = await api.post('/ai/extract-jd-skills', { description: form.description }); setForm({ ...form, mandatory_skills: result.skills.slice(0, 6).map(x => x.name), optional_skills: result.skills.slice(6, 10).map(x => x.name) }) } finally { setSuggesting(false) }
  }
  const addManualSkill = () => { const value = skillText.trim(); if (value && !form.mandatory_skills.includes(value)) setForm({ ...form, mandatory_skills: [...form.mandatory_skills, value] }); setSkillText('') }
  if (!data) return <Loading />
  return <Page eyebrow="Recruiter workspace" title={`Good morning, ${data.company?.name?.split(' ')[0] || 'Recruiter'}.`} subtitle="Build a shortlist that stands up to scrutiny." actions={<><button className="btn btn-secondary" onClick={() => setShowPost(true)}><BriefcaseBusiness size={16} /> Post a role</button><Link className="btn btn-primary" to="/recruiter/applicants"><Users size={16} /> Review applicants</Link></>}>
    <div className="stats-grid"><StatCard label="Open roles" value={data.stats.jobs} meta="Computed from your jobs" icon={BriefcaseBusiness} /><StatCard label="Applicants" value={data.stats.applications} meta="Across your pipeline" icon={Users} tone="teal" /><StatCard label="Shortlisted" value={data.stats.shortlisted} meta="Shortlisted + interview" icon={Target} tone="amber" /><StatCard label="Placements" value={data.stats.placements} meta="Selected candidates" icon={GraduationCap} tone="green" /></div>
    <div className="dashboard-grid recruiter-grid"><section className="panel chart-panel"><div className="panel-head"><div><span className="section-kicker">Pipeline shape</span><h2>Applications by stage</h2></div><span className="decision-note"><ShieldCheck size={13} /> Blind mode available</span></div><ResponsiveContainer width="100%" height={250}><BarChart data={chart} layout="vertical" margin={{ left: 20, right: 16 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="var(--line)" /><XAxis type="number" hide /><YAxis type="category" dataKey="name" axisLine={false} tickLine={false} width={80} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><Tooltip cursor={{ fill: 'var(--surface-2)' }} /><Bar dataKey="value" fill="#4F46E5" radius={[0, 6, 6, 0]} barSize={18} /></BarChart></ResponsiveContainer></section><section className="panel jobs-panel"><div className="panel-head"><div><span className="section-kicker">Your roles</span><h2>My jobs</h2></div><button className="text-link" onClick={() => setShowPost(true)}>Post role</button></div>{data.jobs.map(job => <div className="mini-job" key={job.id}><div><strong>{job.title}</strong><span>{job.location} · {job.applicant_count} applicants</span></div><span className={job.is_approved ? 'tag-open' : 'tag-pending'}>{job.is_approved ? 'Approved' : 'Pending approval'}</span></div>)}</section></div>
    {showPost && <div className="drawer-overlay" onClick={() => setShowPost(false)}><aside className="drawer wide" onClick={e => e.stopPropagation()}><button className="drawer-close" onClick={() => setShowPost(false)}><X size={18} /></button><span className="section-kicker">New role</span><h2>Post a job</h2><div className="field-grid"><label className="field"><span>Title</span><input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><label className="field"><span>Location</span><input value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} /></label></div><label className="field"><span>Description</span><textarea rows="8" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></label><button className="btn btn-outline" onClick={suggest} disabled={suggesting}><Sparkles size={15} /> {suggesting ? 'Extracting…' : 'Suggest skills from description'}</button><div className="chip-row">{form.mandatory_skills.map(s => <SkillChip key={s} type="matched">{s}</SkillChip>)}</div><div className="form-row"><input placeholder="Add mandatory skill" value={skillText} onChange={e => setSkillText(e.target.value)} onKeyDown={e => e.key === 'Enter' && addManualSkill()} /><button className="btn btn-secondary" onClick={addManualSkill}>Add</button></div><div className="field-grid"><label className="field"><span>Minimum CGPA</span><input type="number" step="0.1" value={form.min_cgpa} onChange={e => setForm({ ...form, min_cgpa: Number(e.target.value) })} /></label><label className="field"><span>Deadline</span><input type="date" value={form.deadline} onChange={e => setForm({ ...form, deadline: e.target.value })} /></label></div><div className="drawer-actions"><button className="btn btn-primary full" onClick={post} disabled={!form.title || !form.description}>Submit for approval</button></div></aside></div>}
  </Page>
}
function ApplicantsPage({ setToast }) { const [dash, setDash] = useState(null); const [jobId, setJobId] = useState(null); const [blind, setBlind] = useState(false); const [apps, setApps] = useState([]); const [selected, setSelected] = useState(null); useEffect(() => { api.get('/recruiter/dashboard').then(r => { setDash(r.data); setJobId(r.data.jobs[0]?.id) }).catch(() => {}) }, []); useEffect(() => { if (jobId) api.get(`/jobs/${jobId}/applicants`, { params: { blind } }).then(r => setApps(r.data.items)).catch(() => {}) }, [jobId, blind]); const updateStatus = async (id, status) => { await api.patch(`/applications/${id}/status`, { status }); setApps(apps.map(a => a.id === id ? { ...a, status } : a)); setToast(`Applicant moved to ${status}; notification sent`); setSelected(null) }; if (!dash) return <Loading />; return <Page eyebrow="Talent pipeline" title="Applicants" subtitle="Ranked by fit, with identity controls that keep evidence in focus." actions={<div className="select-wrap"><span>Role</span><select value={jobId || ''} onChange={e => setJobId(e.target.value)}>{dash.jobs.map(j => <option value={j.id} key={j.id}>{j.title}</option>)}</select></div>}><div className="applicant-toolbar"><div><span className="result-count">{apps.length} applicants</span><span className="muted"> · sorted by explainable score</span></div><label className="toggle-label"><span>Blind screening</span><button className={`toggle ${blind ? 'on' : ''}`} onClick={() => setBlind(!blind)}><i /></button><ShieldCheck size={15} /></label></div><div className="panel applicant-table"><div className="table-wrap"><table><thead><tr><th>Rank</th><th>Candidate</th><th>Fit score</th><th>Evidence</th><th>CGPA</th><th>Status</th></tr></thead><tbody>{apps.map((app, i) => <tr key={app.id} onClick={() => setSelected(app)} className="click-row"><td><span className="rank">{String(i + 1).padStart(2, '0')}</span></td><td><div className="candidate"><div className="avatar small-avatar">{blind ? '—' : app.name?.split(' ').map(x => x[0]).join('')}</div><div><strong>{blind ? 'Candidate ' + String(i + 1).padStart(2, '0') : app.name}</strong><span>{blind ? 'Identity hidden' : app.email}</span></div></div></td><td><div className="score-cell"><strong>{Math.round(app.score || 0)}%</strong><div className="tiny-track"><i style={{ width: `${app.score || 0}%` }} /></div></div></td><td><div className="chip-row compact">{(app.breakdown?.matched || []).slice(0, 2).map(s => <SkillChip type="matched" key={s}>{s}</SkillChip>)}{(app.breakdown?.missing || []).slice(0, 1).map(s => <SkillChip type="missing" key={s}>{s}</SkillChip>)}</div></td><td>{app.cgpa}</td><td><StatusBadge status={app.status} /></td></tr>)}</tbody></table></div></div>{selected && <div className="drawer-overlay" onClick={() => setSelected(null)}><aside className="drawer" onClick={e => e.stopPropagation()}><button className="drawer-close" onClick={() => setSelected(null)}><X size={18} /></button><span className="section-kicker">Applicant detail</span><h2>{blind ? 'Candidate ' + selected.id : selected.name}</h2><div className="drawer-score"><ScoreRing score={selected.score} size="lg" /><div><StatusBadge status={selected.status} /><p>Decision-support score</p></div></div><div className="drawer-section"><span className="fit-label">Matched skills</span><div className="chip-row">{(selected.breakdown?.matched || []).map(s => <SkillChip type="matched" key={s}>{s}</SkillChip>)}</div></div><div className="drawer-section"><span className="fit-label">Missing skills</span><div className="chip-row">{(selected.breakdown?.missing || []).map(s => <SkillChip type="missing" key={s}>{s}</SkillChip>)}</div></div><div className="drawer-callout"><ShieldCheck size={16} /><span>Identity signals are {blind ? 'hidden in this view' : 'visible'}.</span></div><div className="drawer-actions"><button className="btn btn-primary full" onClick={() => updateStatus(selected.id, 'Shortlisted')}>Shortlist candidate</button><button className="btn btn-secondary full" onClick={() => updateStatus(selected.id, 'Interview')}>Move to interview</button><button className="btn btn-ghost full" onClick={() => updateStatus(selected.id, 'Rejected')}>Reject with note</button></div></aside></div>}</Page> }

function AdminDashboard({ setToast }) {
  const [stats, setStats] = useState(null); const [insights, setInsights] = useState(null); const [pending, setPending] = useState([]); const [users, setUsers] = useState([]); const [pendingJobs, setPendingJobs] = useState([])
  const load = () => Promise.all([api.get('/admin/stats'), api.get('/admin/placement-insights'), api.get('/admin/companies/pending'), api.get('/admin/users'), api.get('/admin/jobs/pending')]).then(([a,b,c,d,e]) => { setPendingJobs(e.data.items); setStats(a.data); setInsights(b.data); setPending(c.data.items); setUsers(d.data.items) }).catch(() => {})
  useEffect(load, [])
  const approve = async (id) => { await api.patch(`/admin/companies/${id}/approve`); await load(); setToast('Company approved') }
  const approveJob = async (id) => { await api.patch(`/admin/jobs/${id}/approve`); await load(); setToast('Job approved and now visible to students') }
  const rejectJob = async (id) => { await api.patch(`/admin/jobs/${id}/reject`); await load(); setToast('Job rejected') }
  const reset = async () => { if (confirm('Restore original demo data?')) { await api.post('/demo/reset'); await load(); setToast('Demo data restored to its original state') } }
  const toggleUser = async (u) => { await api.patch(`/admin/users/${u.id}/active`, null, { params: { active: !u.is_active } }); await load() }
  if (!stats || !insights) return <Loading />
  const first = stats.over_time?.[0]?.applications || 0; const last = stats.over_time?.[stats.over_time.length - 1]?.applications || 0; const delta = first ? Math.round(((last - first) / first) * 100) : 0
  return <Page eyebrow="Placement office" title="Control center" subtitle="See the system from above — demand, supply, governance and outcomes." actions={<button className="btn btn-outline" onClick={reset}><Activity size={15} /> Reset demo data</button>}>
    <div className="stats-grid"><StatCard label="Students" value={stats.kpis.students} meta="Profiles in database" icon={GraduationCap} /><StatCard label="Approved roles" value={stats.kpis.jobs} meta="Visible to students" icon={BriefcaseBusiness} tone="teal" /><StatCard label="Applications" value={stats.kpis.applications} meta="All statuses" icon={ClipboardCheck} tone="amber" /><StatCard label="Placements" value={stats.kpis.placements} meta="Selected candidates" icon={Target} tone="green" /></div>
    <div className="dashboard-grid admin-top"><section className="panel chart-panel"><div className="panel-head"><div><span className="section-kicker">Applications over time</span><h2>Placement pipeline</h2></div><span className="trend-pill">{delta >= 0 ? '+' : ''}{delta}% across shown periods</span></div><ResponsiveContainer width="100%" height={230}><AreaChart data={stats.over_time}><defs><linearGradient id="fillIndigo" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4F46E5" stopOpacity={0.24} /><stop offset="100%" stopColor="#4F46E5" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="3 3" stroke="var(--line)" vertical={false} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><Tooltip /><Area type="monotone" dataKey="applications" stroke="#4F46E5" strokeWidth={3} fill="url(#fillIndigo)" /></AreaChart></ResponsiveContainer></section><section className="panel"><div className="panel-head"><div><span className="section-kicker">Most requested</span><h2>Skill demand</h2></div><span className="muted">Approved roles</span></div><ResponsiveContainer width="100%" height={230}><BarChart data={stats.demand} layout="vertical" margin={{ left: 18, right: 14 }}><XAxis type="number" hide /><YAxis dataKey="skill" type="category" axisLine={false} tickLine={false} width={83} tick={{ fill: 'var(--muted)', fontSize: 11 }} /><Bar dataKey="demand" fill="#14B8A6" radius={[0, 5, 5, 0]} barSize={13} /></BarChart></ResponsiveContainer></section></div>
    <div className="dashboard-grid admin-bottom"><section className="panel"><div className="panel-head"><div><span className="section-kicker">Governance queue</span><h2>Pending approvals</h2></div><span className="tag-pending">{pending.length + pendingJobs.length} waiting</span></div>{pending.length ? pending.map(company => <div className="approval-row" key={company.id}><div className="company-logo">{company.name.slice(0, 2)}</div><div><strong>{company.name}</strong><span>{company.industry} · {company.location}</span></div><button className="btn btn-secondary" onClick={() => approve(company.id)}>Approve <Check size={14} /></button></div>) : <Empty title="Queue is clear" text="All companies have been reviewed." />}{pendingJobs.map(job => <div className="approval-row" key={`job-${job.id}`}><div className="company-logo">{(job.company || 'JB').slice(0, 2)}</div><div><strong>{job.title}</strong><span>Job · {job.company}</span></div><button className="btn btn-secondary" onClick={() => approveJob(job.id)}>Approve <Check size={14} /></button><button className="btn btn-ghost" onClick={() => rejectJob(job.id)}>Reject</button></div>)}</section><section className="panel model-panel"><div className="panel-head"><div><span className="section-kicker">Model evaluation</span><h2>Placement prediction</h2></div><span className="synthetic-tag">Synthetic data</span></div><div className="metric-grid">{Object.entries(insights.metrics || {}).slice(0, 4).map(([key, val]) => <div key={key}><strong>{Math.round(val * 100)}%</strong><span>{key.replace('_', ' ')}</span></div>)}</div><div className="evaluation-table"><div className="eval-head"><span>Model</span><span>ρ</span><span>NDCG@5</span></div>{(insights.evaluation || []).map(row => <div className={`eval-row ${row.model === 'Hybrid' ? 'best' : ''}`} key={row.model}><span>{row.model}</span><strong>{row.spearman}</strong><strong>{row.ndcg}</strong></div>)}</div><p className="disclaimer">Synthetic labeled data · evaluation is research/demo evidence, not hiring performance.</p></section></div>
    <section className="panel"><div className="panel-head"><div><span className="section-kicker">Administration</span><h2>User access</h2></div><span className="muted">{users.length} shown</span></div><div className="table-wrap"><table><thead><tr><th>Email</th><th>Role</th><th>Status</th><th /></tr></thead><tbody>{users.map(u => <tr key={u.id}><td>{u.email}</td><td>{u.role}</td><td><StatusBadge status={u.is_active ? 'Active' : 'Rejected'} /></td><td><button className="btn btn-ghost" onClick={() => toggleUser(u)}>{u.is_active ? 'Deactivate' : 'Activate'}</button></td></tr>)}</tbody></table></div></section>
  </Page>
}
function NotificationsPage() { const [data, setData] = useState(null); useEffect(() => { api.get('/notifications').then(r => setData(r.data)).catch(() => {}) }, []); if (!data) return <Loading />; return <Page eyebrow="Your activity" title="Notifications" subtitle="Small signals that keep every handoff connected."><div className="panel notifications-list"><div className="panel-head"><div><span className="section-kicker">Inbox</span><h2>{data.unread} unread updates</h2></div><button className="btn btn-outline" onClick={() => api.post('/notifications/read-all').then(() => setData({ ...data, unread: 0, items: data.items.map(x => ({ ...x, is_read: 1 })) }))}>Mark all read</button></div>{data.items.map(n => <div className={`notification-row ${n.is_read ? '' : 'unread'}`} key={n.id}><div className="notification-icon"><Bell size={16} /></div><div><strong>{n.message}</strong><span>{new Date(n.created_at).toLocaleString('en-IN', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' })}</span></div>{!n.is_read && <span className="unread-dot" />}</div>)}</div></Page> }
function Loading() { return <main className="page"><div className="loading-page"><div className="spinner" /><span>Loading your workspace…</span></div></main> }

function Register() { const [role, setRole] = useState('student'); const [form, setForm] = useState({ email: '', password: '', full_name: '' }); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const navigate = useNavigate(); const submit = async (e) => { e.preventDefault(); setError(''); if (form.password.length < 6) { setError('Password must be at least 6 characters.'); return } try { await api.post('/auth/register', { ...form, role }); setMessage('Account created. Sign in to continue.'); setTimeout(() => navigate('/login'), 700) } catch (err) { setError(err.response?.data?.error?.message || err.response?.data?.detail || 'Could not create account.') } }; return <div className="login-page"><Link to="/" className="brand login-brand"><div className="brand-mark"><Activity size={19} /></div><span>SkillTrack</span></Link><form className="login-card register-card" onSubmit={submit}><span className="section-kicker">Create workspace</span><h2>Start with your profile</h2><div className="role-toggle"><button type="button" className={role === 'student' ? 'active' : ''} onClick={() => setRole('student')}>Student</button><button type="button" className={role === 'recruiter' ? 'active' : ''} onClick={() => setRole('recruiter')}>Recruiter</button></div><label className="field"><span>Name</span><input required value={form.full_name} onChange={e => setForm({ ...form, full_name: e.target.value })} /></label><label className="field"><span>Email</span><input type="email" required value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label><label className="field"><span>Password</span><input type="password" minLength={6} required value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label>{error && <div className="inline-error">{error}</div>}{message && <div className="inline-success">{message}</div>}<button className="btn btn-primary full">Create account</button><Link className="text-link" to="/login">Back to sign in</Link></form></div> }
function ProfilePage({ setToast }) {
  const [data, setData] = useState(null); const [skill, setSkill] = useState(''); const [form, setForm] = useState({})
  const load = () => api.get('/students/me').then(r => { setData(r.data); setForm(r.data.profile || {}) }).catch(() => setToast('Unable to load profile'))
  useEffect(() => { load() }, [])
  if (!data) return <Loading />
  const save = async () => { try { await api.put('/students/me', form); await load(); setToast('Profile saved') } catch (e) { setToast(e.response?.data?.detail || 'Could not save profile') } }
  const addSkill = async () => { if (!skill.trim()) return; try { await api.post('/students/me/skills', null, { params: { name: skill, proficiency: 3 } }); setSkill(''); await load() } catch (e) { setToast(e.response?.data?.detail || 'Skill is not in the taxonomy') } }
  const removeSkill = async (name) => { await api.delete(`/students/me/skills/${encodeURIComponent(name)}`); await load() }
  const removeProject = async (id) => { await api.delete(`/students/me/projects/${id}`); await load() }
  const removeCertificate = async (id) => { await api.delete(`/students/me/certificates/${id}`); await load() }
  return <Page eyebrow="Student profile" title={data.profile.full_name || 'Your profile'} subtitle="Keep your evidence current so every fit score stays explainable.">
    <div className="profile-grid"><section className="panel"><div className="panel-head"><div><span className="section-kicker">Personal + education</span><h2>Profile details</h2></div></div><div className="field-grid"><label className="field"><span>Name</span><input value={form.full_name || ''} onChange={e => setForm({ ...form, full_name: e.target.value })} /></label><label className="field"><span>College</span><input value={form.college || ''} onChange={e => setForm({ ...form, college: e.target.value })} /></label><label className="field"><span>Course</span><input value={form.course || ''} onChange={e => setForm({ ...form, course: e.target.value })} /></label><label className="field"><span>CGPA</span><input type="number" step="0.1" value={form.cgpa ?? ''} onChange={e => setForm({ ...form, cgpa: Number(e.target.value) })} /></label><label className="field"><span>Graduation year</span><input type="number" value={form.graduation_year ?? ''} onChange={e => setForm({ ...form, graduation_year: Number(e.target.value) })} /></label></div><label className="field"><span>Bio</span><textarea rows="4" value={form.bio || ''} onChange={e => setForm({ ...form, bio: e.target.value })} /></label><button className="btn btn-primary" onClick={save}>Save profile</button></section><section className="panel"><div className="panel-head"><div><span className="section-kicker">Skills</span><h2>{data.skills.length} canonical skills</h2></div></div><div className="chip-row">{data.skills.map(x => <button className="chip matched" key={x.name} onClick={() => removeSkill(x.name)}>{x.name} · {x.proficiency}/5 ×</button>)}</div><div className="form-row"><input placeholder="Add a taxonomy skill" value={skill} onChange={e => setSkill(e.target.value)} onKeyDown={e => e.key === 'Enter' && addSkill()} /><button className="btn btn-primary" onClick={addSkill}>Add skill</button></div></section></div>
    <div className="profile-grid"><section className="panel"><div className="panel-head"><div><span className="section-kicker">Projects</span><h2>Evidence you can discuss</h2></div></div>{data.projects.map(x => <div className="list-row" key={x.id}><div><strong>{x.title}</strong><span>{x.tech_stack}</span></div><button className="btn btn-ghost" onClick={() => removeProject(x.id)}>Delete</button></div>)}</section><section className="panel"><div className="panel-head"><div><span className="section-kicker">Certificates</span><h2>Credentials</h2></div></div>{data.certificates.map(x => <div className="list-row" key={x.id}><div><strong>{x.title}</strong><span>{x.issuer} · {x.year}</span></div><button className="btn btn-ghost" onClick={() => removeCertificate(x.id)}>Delete</button></div>)}</section></div>
  </Page>
}
export default App
